export type Money = {
  cents: number;
  currency: string;
};

const MONEY_PATTERN = /^(-?)(\d+)(?:\.(\d{1,2}))? ([A-Z]{3})$/;

/**
 * Parses a string like "12.34 EUR" or "-0.5 USD" into a Money value.
 * Returns undefined for anything that does not match: at most two decimals,
 * a three-letter uppercase currency code, no surrounding whitespace.
 */
export function parseMoney(text: string): Money | undefined {
  const match = MONEY_PATTERN.exec(text);
  if (match === null) {
    return undefined;
  }

  const [, sign, whole, fraction = '', currency] = match;
  const cents = Number(whole) * 100 + Number(fraction.padEnd(2, '0'));
  return { cents: sign === '-' ? -cents : cents, currency };
}

/** Formats a Money value as a string with exactly two decimals. */
export function formatMoney(m: Money): string {
  const sign = m.cents < 0 ? '-' : '';
  const absolute = Math.abs(m.cents);
  const whole = Math.floor(absolute / 100);
  const fraction = String(absolute % 100).padStart(2, '0');
  return `${sign}${whole}.${fraction} ${m.currency}`;
}

/** Adds two Money values, throwing if their currencies differ. */
export function addMoney(a: Money, b: Money): Money {
  if (a.currency !== b.currency) {
    throw new Error(`currency mismatch: ${a.currency} vs ${b.currency}`);
  }
  return { cents: a.cents + b.cents, currency: a.currency };
}

import assert from 'node:assert/strict';
import test from 'node:test';

import { addMoney, formatMoney, parseMoney, type Money } from './money.ts';

test('parseMoney reads a whole amount with two decimals', () => {
  assert.deepEqual(parseMoney('12.34 EUR'), { cents: 1234, currency: 'EUR' });
});

test('parseMoney reads a negative amount with one decimal', () => {
  assert.deepEqual(parseMoney('-0.5 USD'), { cents: -50, currency: 'USD' });
});

test('parseMoney reads an amount without decimals', () => {
  assert.deepEqual(parseMoney('7 GBP'), { cents: 700, currency: 'GBP' });
});

test('parseMoney treats a zero fraction as zero', () => {
  assert.deepEqual(parseMoney('0.00 JPY'), { cents: 0, currency: 'JPY' });
});

test('parseMoney keeps a negative zero amount at zero', () => {
  assert.deepEqual(parseMoney('-0.00 EUR'), { cents: -0, currency: 'EUR' });
});

test('parseMoney rejects three decimals', () => {
  assert.equal(parseMoney('12.345 EUR'), undefined);
});

test('parseMoney rejects a missing currency', () => {
  assert.equal(parseMoney('12.34'), undefined);
});

test('parseMoney rejects a lowercase currency', () => {
  assert.equal(parseMoney('12.34 eur'), undefined);
});

test('parseMoney rejects a two-letter currency', () => {
  assert.equal(parseMoney('12.34 EU'), undefined);
});

test('parseMoney rejects a four-letter currency', () => {
  assert.equal(parseMoney('12.34 EURO'), undefined);
});

test('parseMoney rejects a missing space before the currency', () => {
  assert.equal(parseMoney('12.34EUR'), undefined);
});

test('parseMoney rejects a trailing dot', () => {
  assert.equal(parseMoney('12. EUR'), undefined);
});

test('parseMoney rejects surrounding whitespace', () => {
  assert.equal(parseMoney(' 12.34 EUR '), undefined);
});

test('parseMoney rejects an empty string', () => {
  assert.equal(parseMoney(''), undefined);
});

test('parseMoney rejects a thousands separator', () => {
  assert.equal(parseMoney('1,234.00 EUR'), undefined);
});

test('parseMoney rejects a leading plus sign', () => {
  assert.equal(parseMoney('+12.34 EUR'), undefined);
});

test('formatMoney prints two decimals', () => {
  assert.equal(formatMoney({ cents: 1234, currency: 'EUR' }), '12.34 EUR');
});

test('formatMoney pads a single decimal', () => {
  assert.equal(formatMoney({ cents: 50, currency: 'USD' }), '0.50 USD');
});

test('formatMoney pads a whole amount', () => {
  assert.equal(formatMoney({ cents: 700, currency: 'GBP' }), '7.00 GBP');
});

test('formatMoney prints a negative amount', () => {
  assert.equal(formatMoney({ cents: -50, currency: 'USD' }), '-0.50 USD');
});

test('formatMoney prints zero', () => {
  assert.equal(formatMoney({ cents: 0, currency: 'EUR' }), '0.00 EUR');
});

test('formatMoney round-trips through parseMoney', () => {
  const samples: Money[] = [
    { cents: 1234, currency: 'EUR' },
    { cents: -50, currency: 'USD' },
    { cents: 0, currency: 'JPY' },
    { cents: 99, currency: 'GBP' },
  ];
  for (const sample of samples) {
    assert.deepEqual(parseMoney(formatMoney(sample)), sample);
  }
});

test('addMoney adds matching currencies', () => {
  assert.deepEqual(
    addMoney({ cents: 1234, currency: 'EUR' }, { cents: 66, currency: 'EUR' }),
    { cents: 1300, currency: 'EUR' },
  );
});

test('addMoney handles negatives', () => {
  assert.deepEqual(
    addMoney({ cents: 100, currency: 'USD' }, { cents: -250, currency: 'USD' }),
    { cents: -150, currency: 'USD' },
  );
});

test('addMoney throws on a currency mismatch', () => {
  assert.throws(
    () => addMoney({ cents: 100, currency: 'EUR' }, { cents: 100, currency: 'USD' }),
    /currency mismatch/,
  );
});

